import base64,hashlib,json,os,socket
from pathlib import Path
payload=json.loads('{"RELEASE.json": {"sha256": "9b995c701afd4fa787b0040a1ace47c9a58890232535554649fcb4a339e1f03b", "base64": ""}, "RECEIPT.json": {"sha256": "3069a092c175b3bac8555d87d8f3cd28ed0c70eb3249e3030b47cdfae69c854f", "base64": ""}, "REVIEW.md": {"sha256": "240e73468ad8f5b5fabab8daffa3f71922edcbeced5498ad91cd0b18140b0be3", "base64": ""}}')
assert socket.gethostname().split('.')[0]=='h100-9'
d=Path('/dataset/shaoshitong/search-r1-rl/tree-grpo/instruct300/probability-probe-release-r3-audits');d.mkdir(parents=True,exist_ok=True)
out={}
for name,item in payload.items():
 b=base64.b64decode(item['base64']); assert hashlib.sha256(b).hexdigest()==item['sha256']
 p=d/name
 try:
  with p.open('xb') as f:f.write(b);f.flush();os.fsync(f.fileno())
 except FileExistsError:assert p.read_bytes()==b, 'Existing signed metadata differs'
 actual=p.read_bytes();assert hashlib.sha256(actual).hexdigest()==item['sha256']
 out[name]={'path':str(p),'sha256':item['sha256'],'bytes':len(actual)}
intent=Path('/dataset/shaoshitong/search-r1-rl/tree-grpo/instruct300/PROBABILITY_PROBE_HEADER_REPAIR_ONCE-3280.json')
print(json.dumps({'host':socket.gethostname(),'files':out,'fixed_intent_exists':intent.exists(),'fixed_result_exists':Path(str(intent)+'.result.json').exists(),'old_intent_preserved':Path('/dataset/shaoshitong/search-r1-rl/tree-grpo/instruct300/PROBABILITY_PROBE_ONCE-3268.json').is_file(),'assets_transferred':False},sort_keys=True))
